create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,display_name text,avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.accounts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,provider text not null check(provider in ('gmail','outlook','imap','smtp')),email_address text not null,display_name text,status text not null default 'disconnected',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.contacts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,email text not null,organization text,notes text,tags text[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.threads(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id uuid not null references public.accounts(id) on delete cascade,subject text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),thread_id uuid not null references public.threads(id) on delete cascade,sender text not null,recipients text[] not null default '{}',cc text[] not null default '{}',bcc text[] not null default '{}',subject text,body text,body_html text,received_at timestamptz,sent_at timestamptz,is_read boolean not null default false,is_starred boolean not null default false,has_attachments boolean not null default false);
create table if not exists public.research_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,description text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.drafts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,account_id uuid references public.accounts(id) on delete set null,recipients text[] not null default '{}',cc text[] not null default '{}',bcc text[] not null default '{}',subject text,body text,research_session_id uuid references public.research_sessions(id) on delete set null,version bigint not null default 1,updated_at timestamptz not null default now());
create table if not exists public.attachments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,message_id uuid references public.messages(id) on delete cascade,filename text not null,mime_type text,size bigint,storage_path text not null);
create table if not exists public.research_sources(id uuid primary key default gen_random_uuid(),research_session_id uuid not null references public.research_sessions(id) on delete cascade,url text not null,title text,domain text,snippet text,notes text,created_at timestamptz not null default now());
create table if not exists public.research_notes(id uuid primary key default gen_random_uuid(),research_session_id uuid not null references public.research_sessions(id) on delete cascade,title text not null,content text not null default '',source_id uuid references public.research_sources(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.email_templates(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,subject text,body text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.settings(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,settings_json jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create index if not exists idx_accounts_user on public.accounts(user_id);create index if not exists idx_contacts_user on public.contacts(user_id);create index if not exists idx_threads_user on public.threads(user_id);create index if not exists idx_messages_thread on public.messages(thread_id);create index if not exists idx_drafts_user on public.drafts(user_id);create index if not exists idx_research_user on public.research_sessions(user_id);create index if not exists idx_sources_session on public.research_sources(research_session_id);create index if not exists idx_notes_session on public.research_notes(research_session_id);create index if not exists idx_templates_user on public.email_templates(user_id);
alter table public.profiles enable row level security;alter table public.accounts enable row level security;alter table public.contacts enable row level security;alter table public.threads enable row level security;alter table public.messages enable row level security;alter table public.drafts enable row level security;alter table public.attachments enable row level security;alter table public.research_sessions enable row level security;alter table public.research_sources enable row level security;alter table public.research_notes enable row level security;alter table public.email_templates enable row level security;alter table public.settings enable row level security;
create policy profiles_owner on public.profiles for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy accounts_owner on public.accounts for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy contacts_owner on public.contacts for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy threads_owner on public.threads for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy messages_select on public.messages for select to authenticated using (exists(select 1 from public.threads t where t.id=thread_id and t.user_id=(select auth.uid())));
create policy messages_insert on public.messages for insert to authenticated with check (exists(select 1 from public.threads t where t.id=thread_id and t.user_id=(select auth.uid())));
create policy messages_update on public.messages for update to authenticated using (exists(select 1 from public.threads t where t.id=thread_id and t.user_id=(select auth.uid()))) with check (exists(select 1 from public.threads t where t.id=thread_id and t.user_id=(select auth.uid())));
create policy messages_delete on public.messages for delete to authenticated using (exists(select 1 from public.threads t where t.id=thread_id and t.user_id=(select auth.uid())));
create policy drafts_owner on public.drafts for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy attachments_owner on public.attachments for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy research_owner on public.research_sessions for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy sources_select on public.research_sources for select to authenticated using (exists(select 1 from public.research_sessions r where r.id=research_session_id and r.user_id=(select auth.uid())));
create policy sources_insert on public.research_sources for insert to authenticated with check (exists(select 1 from public.research_sessions r where r.id=research_session_id and r.user_id=(select auth.uid())));
create policy sources_update on public.research_sources for update to authenticated using (exists(select 1 from public.research_sessions r where r.id=research_session_id and r.user_id=(select auth.uid()))) with check (exists(select 1 from public.research_sessions r where r.id=research_session_id and r.user_id=(select auth.uid())));
create policy sources_delete on public.research_sources for delete to authenticated using (exists(select 1 from public.research_sessions r where r.id=research_session_id and r.user_id=(select auth.uid())));
create policy notes_owner on public.research_notes for all to authenticated using (exists(select 1 from public.research_sessions r where r.id=research_session_id and r.user_id=(select auth.uid()))) with check (exists(select 1 from public.research_sessions r where r.id=research_session_id and r.user_id=(select auth.uid())));
create policy templates_owner on public.email_templates for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy settings_owner on public.settings for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
grant select,insert,update,delete on all tables in schema public to authenticated;